"use client";

import { useState, useEffect } from "react";

export default function Home() {
  const [email, setEmail] = useState("");
  const [runId, setRunId] = useState<string | null>(null);
  const [runData, setRunData] = useState<any>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSignUp = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    try {
      const res = await fetch("/api/signup", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email }),
      });
      const data = await res.json();
      if (data.runId) {
        setRunId(data.runId);
      } else {
        setError(data.error || "Failed to sign up");
      }
    } catch (err) {
      setError("An error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleVerify = async (token: string) => {
    setLoading(true);
    try {
      const res = await fetch(`/api/verify?token=${token}`, {
        method: "POST",
      });
      const data = await res.json();
      if (!data.success) {
        setError(data.error || "Failed to verify");
      }
    } catch (err) {
      setError("An error occurred during verification");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (!runId) return;

    const poll = async () => {
      try {
        const res = await fetch(`https://api.trigger.dev/api/v3/runs/${runId}`, {
          headers: {
            Authorization: `Bearer ${process.env.NEXT_PUBLIC_TRIGGER_SECRET_KEY}`,
          },
        });
        const data = await res.json();
        setRunData(data);
      } catch (err) {
        console.error("Polling error:", err);
      }
    };

    poll();
    const interval = setInterval(poll, 2000);
    return () => clearInterval(interval);
  }, [runId]);

  const status = runData?.metadata?.status || runData?.status;
  const waitpointToken = runData?.waitpoints?.[0]?.id; // Simplification: get the first waitpoint token ID

  return (
    <main className="flex min-h-screen flex-col items-center justify-center p-24 bg-gray-50">
      <div className="z-10 max-w-md w-full items-center justify-between font-mono text-sm bg-white p-8 rounded-xl shadow-md">
        <h1 className="text-2xl font-bold mb-6 text-center">Onboarding Flow</h1>

        {!runId ? (
          <form onSubmit={handleSignUp} className="space-y-4">
            <div>
              <label htmlFor="email" className="block text-sm font-medium text-gray-700">Email Address</label>
              <input
                type="email"
                id="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
                className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm p-2"
                placeholder="you@example.com"
              />
            </div>
            <button
              type="submit"
              disabled={loading}
              className="w-full bg-blue-600 text-white p-2 rounded-md hover:bg-blue-700 disabled:opacity-50"
            >
              {loading ? "Starting..." : "Sign Up"}
            </button>
          </form>
        ) : (
          <div className="space-y-4">
            <div className="p-4 bg-gray-100 rounded-md">
              <p className="font-semibold">Run ID:</p>
              <p className="text-xs break-all">{runId}</p>
            </div>

            <div className="p-4 bg-gray-100 rounded-md">
              <p className="font-semibold">Current Status:</p>
              <p className={`font-bold ${status === 'Active' ? 'text-green-600' : 'text-orange-600'}`}>
                {status || "Initializing..."}
              </p>
            </div>

            {status === "Waiting for verification" && waitpointToken && (
              <div className="mt-6">
                <button
                  onClick={() => handleVerify(waitpointToken)}
                  disabled={loading}
                  className="w-full bg-green-600 text-white p-2 rounded-md hover:bg-green-700 disabled:opacity-50"
                >
                  {loading ? "Verifying..." : "Simulate Email Verification"}
                </button>
                <p className="text-xs text-center mt-2 text-gray-500">
                  Clicking this will complete the waitpoint token.
                </p>
              </div>
            )}

            {status === "Active" && (
              <div className="mt-6 p-4 bg-green-50 border border-green-200 rounded-md text-center">
                <p className="text-green-700 font-bold">Onboarding Complete!</p>
              </div>
            )}
          </div>
        )}

        {error && (
          <div className="mt-4 p-2 bg-red-100 text-red-700 text-xs rounded">
            {error}
          </div>
        )}
      </div>
    </main>
  );
}

